void CSCNativeExecution::failGlobal(CSCError code,const std::string&message,int32_t engine){if(failed_)return;failed_=true;error_code_=code;error_message_=message;failed_engine_=engine;}
void CSCNativeExecution::latchFailure(const CSCDescriptorEngine&e){failGlobal(e.errorCode(),e.errorMessage(),int32_t(e.globalBG()));}
DRAMSim::PIMRank& CSCNativeExecution::targetRank(uint32_t bg){if(bg>=64)throw std::out_of_range("CSC BG");return *impl_->mem->channels.at(bg/4)->ranks->at(0)->pimRank;}
CSCBGAInputResult CSCNativeExecution::submitBGA(const CSCBGAPartialBatch& batch){auto result=targetRank(batch.global_bg_id).submitCSCBGAPartialBatch(batch);if(result==CSCBGAInputResult::ACCEPTED){for(const auto&partial:batch.payload.partials){if(partial.row_idx>=bga_validation_collector_.shadow_accepted_y_double.size())throw std::out_of_range("BGA shadow row");bga_validation_collector_.shadow_accepted_y_double[partial.row_idx]+=double(partial.value);}}return result;}
bool CSCNativeExecution::requestBGAFinalDrain(const CSCBGAProducerIdentity& identity){if(identity.logical_stream_id!=kCSCM7ALogicalStream||identity.generation!=generation_)throw std::invalid_argument("BGA final-drain identity mismatch");return targetRank(identity.global_bg_id).requestCSCBGAFinalDrain(identity.global_bg_id);}
bool CSCNativeExecution::hasBGAOutput(uint32_t bg)const{if(!bga_config_.enabled||!bga_output_callbacks_.complete())throw std::logic_error("BGA output port disabled");if(bg>=kCSCGlobalBGCount)throw std::out_of_range("CSC BG");return bga_output_callbacks_.has_output(bg);}
