void CSCNativeExecution::recordAcceptedBGAOutputStats(const CSCBGAOutput&output){saturatingIncrement(execution_stats_.bga_outputs_accepted);saturatingAdd(execution_stats_.bga_output_contributions_accepted,output.contribution_count);if(output.reason==CSCBGAOutputReason::CAPACITY_EVICTION)saturatingIncrement(execution_stats_.bga_capacity_outputs_accepted);else saturatingIncrement(execution_stats_.bga_final_drain_outputs_accepted);execution_stats_.last_bga_output_accept_cycle=cycle_;}
