void CSCNativeExecution::serviceValidationBGAOutputs(){if(!bga_config_.enabled||bga_config_.output_consumer_mode!=CSCBGAOutputConsumerMode::VALIDATION_ROUND_ROBIN||failed_)return;std::array<bool,kCSCGlobalBGCount>accepted_this_cycle{};bool accepted=false;for(uint32_t n=0;n<bga_config_.validation_consumer_accepts_per_cycle&&!failed_;++n){bool found=false;for(uint32_t scanned=0;scanned<kCSCGlobalBGCount;++scanned){uint32_t bg=(validation_round_robin_cursor_+scanned)%kCSCGlobalBGCount;if(accepted_this_cycle[bg]||!bga_output_callbacks_.has_output(bg))continue;try{acceptBGAOutput(bg);}catch(const std::exception&){return;}accepted_this_cycle[bg]=true;validation_round_robin_cursor_=(bg+1)%kCSCGlobalBGCount;found=accepted=true;break;}if(!found)break;}if(accepted)saturatingIncrement(execution_stats_.validation_output_drain_cycles);}
void CSCNativeExecution::servicePartialWritebackBGAOutputs(){if(!partial_result_path_||failed_)return;const uint32_t count=partial_result_path_->globalBGCount();const uint32_t start=partial_writeback_round_robin_cursor_;uint32_t accepted=0;for(uint32_t scanned=0;scanned<count&&accepted<bga_config_.partial_writeback_accepts_per_cycle;++scanned){uint32_t bg=(start+scanned)%count;if(!bga_output_callbacks_.has_output(bg))continue;const auto output=bga_output_callbacks_.peek_output(bg);const auto result=transferCSCBGAOutput(bg,bga_output_callbacks_,*partial_result_path_);if(partial_result_path_->hasError()){failGlobal(CSCError::INTERNAL_INVARIANT,partial_result_path_->errorMessage(),int32_t(bg));return;}if(result!=CSCBGAOutputTransferResult::ACCEPTED)return;recordAcceptedBGAOutputStats(output);partial_writeback_round_robin_cursor_=(bg+1)%count;++accepted;}}
void CSCNativeExecution::stepPartialResultWriteback(){if(!partial_result_path_||failed_)return;std::vector<bool> complete(partial_result_path_->globalBGCount());for(uint32_t bg=0;bg<complete.size();++bg){const auto&bga=bankGroupAccumulator(bg);complete[bg]=bga.finalDrainComplete()&&!bga.hasOutput();}partial_result_path_->step(cycle_,complete);if(partial_result_path_->hasError())failGlobal(CSCError::INTERNAL_INVARIANT,partial_result_path_->errorMessage());}
bool CSCNativeExecution::bgaComputeSubmitComplete()const{if(!bga_config_.enabled||failed_)return false;for(const auto&e:engines_)if(!e->computeSubmitDone()||e->pendingBGABatch())return false;return true;}
bool CSCNativeExecution::bgaDrainComplete()const{if(!bga_config_.enabled||failed_||!production_bga_enabled_)return false;for(uint32_t bg=0;bg<kCSCGlobalBGCount;++bg){const auto&bga=bankGroupAccumulator(bg);if(!bga.finalDrainComplete()||bga.hasOutput())return false;}return true;}
bool CSCNativeExecution::bgaValidationSemanticMatches(double tolerance)const{if(tolerance<0||bga_validation_collector_.validation_y_double.size()!=bga_validation_collector_.shadow_accepted_y_double.size())return false;for(size_t i=0;i<bga_validation_collector_.validation_y_double.size();++i){double a=bga_validation_collector_.validation_y_double[i],b=bga_validation_collector_.shadow_accepted_y_double[i];if(std::isnan(a)||std::isnan(b)){if(!(std::isnan(a)&&std::isnan(b)))return false;continue;}if(std::isinf(a)||std::isinf(b)){if(a!=b)return false;continue;}if(std::abs(a-b)>tolerance*(1.0+std::abs(b)))return false;}return true;}
bool CSCNativeExecution::bgaExecutionComplete()const{if(!bgaComputeSubmitComplete()||!bgaDrainComplete()||failed_)return false;uint64_t accepted=0;for(const auto&e:engines_){const uint64_t value=e->counters().accepted_bga_partials;if(value>std::numeric_limits<uint64_t>::max()-accepted)return false;accepted+=value;}return bga_validation_collector_.accepted_contributions==accepted;}
bool CSCNativeExecution::partialWritebackComplete()const{return partial_result_path_&&bgaDrainComplete()&&partial_result_path_->partialWritebackComplete()&&!failed_;}
bool CSCNativeExecution::hostReadTransportComplete()const{return partial_result_path_&&partial_result_path_->hostReadTransportComplete()&&!failed_;}
bool CSCNativeExecution::hostReadbackComplete()const{return partial_result_path_&&partial_result_path_->hostReadbackComplete()&&!failed_;}
bool CSCNativeExecution::hostReductionComplete()const{return partial_result_path_&&partial_result_path_->hostReductionComplete()&&!failed_;}
bool CSCNativeExecution::endToEndConservationValid()const{if(!partial_result_path_||!hostReductionComplete())return false;uint64_t accepted_contributions=0;for(const auto&e:engines_){const uint64_t value=e->counters().accepted_bga_partials;if(value>std::numeric_limits<uint64_t>::max()-accepted_contributions)return false;accepted_contributions+=value;}const auto&w=partial_result_path_->counters();const auto&r=partial_result_path_->readbackCounters();const auto&h=partial_result_path_->reductionCounters();return accepted_contributions==nnz_&&execution_stats_.bga_output_contributions_accepted==nnz_&&execution_stats_.bga_output_contributions_accepted==w.partial_record_contribution_sum&&w.partial_record_contribution_sum==r.readback_contribution_sum&&r.readback_contribution_sum==h.reduced_contribution_count&&execution_stats_.bga_outputs_accepted==w.partial_records_generated&&w.partial_records_generated==r.readback_records&&r.readback_records==h.reduced_partial_records&&w.writeback_transferred_bytes==r.readback_transferred_bytes&&w.writeback_useful_bytes==r.readback_useful_bytes&&w.writeback_padding_bytes==r.readback_padding_bytes&&w.writeback_useful_bytes==uint64_t(kCSCPartialResultRecordBytes)*w.partial_records_generated&&w.writeback_transferred_bytes==uint64_t(kCSCPartialResultBurstBytes)*w.total_writeback_bursts&&h.fp32_host_add_count==h.reduced_partial_records&&partial_result_path_->hostReducedResult().size()==rows_;}
bool CSCNativeExecution::endToEndSpMVComplete()const{return launched_&&!failed_&&bga_config_.enabled&&bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::PARTIAL_RESULT_WRITEBACK&&result_valid_generation_==generation_&&bgaComputeSubmitComplete()&&bgaDrainComplete()&&partialWritebackComplete()&&hostReadbackComplete()&&hostReductionComplete()&&endToEndConservationValid();}
