bool CSCNativeExecution::hasHostReturnedBurst()const{return partial_result_path_&&partial_result_path_->hasHostReturnedBurst();}
const CSCHostReturnedBurst& CSCNativeExecution::peekHostReturnedBurst()const{if(!partial_result_path_)throw std::logic_error("partial-result writeback disabled");return partial_result_path_->peekHostReturnedBurst();}
void CSCNativeExecution::acceptHostReturnedBurst(){if(!partial_result_path_)throw std::logic_error("partial-result writeback disabled");partial_result_path_->acceptHostReturnedBurst();}
const std::vector<float>& CSCNativeExecution::hostReducedResult()const{if(!partial_result_path_)throw std::logic_error("partial-result writeback disabled");return partial_result_path_->hostReducedResult();}
