CSCBGAExecutionState CSCNativeExecution::bgaExecutionState()const{if(!bga_config_.enabled)return CSCBGAExecutionState::DISABLED;if(failed_)return CSCBGAExecutionState::ERROR;if(!bgaComputeSubmitComplete())return CSCBGAExecutionState::RUNNING_COMPUTE;if(bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::PARTIAL_RESULT_WRITEBACK&&endToEndSpMVComplete())return CSCBGAExecutionState::COMPLETE;if(bga_config_.output_consumer_mode!=CSCBGAOutputConsumerMode::PARTIAL_RESULT_WRITEBACK&&bgaExecutionComplete())return CSCBGAExecutionState::COMPLETE;if(bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::EXTERNAL)for(uint32_t bg=0;bg<kCSCGlobalBGCount;++bg)if(bga_output_callbacks_.has_output(bg))return CSCBGAExecutionState::WAITING_FOR_EXTERNAL_OUTPUT_CONSUMER;return CSCBGAExecutionState::DRAINING_BGA;}
const CSCBankGroupAccumulator& CSCNativeExecution::bankGroupAccumulator(uint32_t bg)const{if(!production_bga_enabled_)throw std::logic_error("production BGA disabled");if(bg>=64)throw std::out_of_range("CSC BG");auto*rank=impl_->mem->channels.at(bg/4)->ranks->at(0)->pimRank.get();return rank->cscBGA(rank->cscLocalBG(bg));}
void CSCNativeExecution::updateMLP(){uint64_t n=outstanding_.size();execution_stats_.maximum_global_outstanding=std::max(execution_stats_.maximum_global_outstanding,n);if(n)execution_stats_.cycles_with_outstanding_ge_1++;if(n>=2)execution_stats_.cycles_with_outstanding_ge_2++;execution_stats_.outstanding_cycle_integral+=n;std::array<uint64_t,16>ch{};for(auto&p:outstanding_){auto bg=p.second->globalBG();ch[bg/4]++;}for(auto n2:ch)execution_stats_.maximum_outstanding_per_channel=std::max(execution_stats_.maximum_outstanding_per_channel,n2);for(auto&e:engines_)execution_stats_.maximum_outstanding_per_engine=std::max(execution_stats_.maximum_outstanding_per_engine,e->maximumOutstanding());}
void CSCNativeExecution::configureBGAIntegration(const CSCBGAIntegrationConfig&config,CSCBGAProducerCallbacks producer,CSCBGAOutputPortCallbacks output){if(launched_||bga_configuration_locked_)throw std::logic_error("configure BGA integration after native launch");config.validate();if(config.enabled&&!producer.complete())throw std::invalid_argument("enabled native BGA producer callbacks incomplete");if(config.enabled&&!output.complete())throw std::invalid_argument("enabled native BGA output port callbacks incomplete");for(auto&e:engines_)e->configureBGAIntegration(config,producer);bga_config_=config;bga_output_callbacks_=config.enabled?std::move(output):CSCBGAOutputPortCallbacks{};production_bga_enabled_=false;}
void CSCNativeExecution::enableProductionBGAIntegration(const CSCBGAIntegrationConfig&config){if(launched_||bga_configuration_locked_)throw std::logic_error("enable production BGA after native launch");config.validate();if(!config.enabled)throw std::invalid_argument("production BGA configuration is disabled");bga_config_=config;bga_output_callbacks_={};production_bga_enabled_=true;}
void CSCNativeExecution::configurePartialResultWriteback(const CSCPartialResultPathConfig&config){if(launched_||bga_configuration_locked_)throw std::logic_error("configure partial-result writeback after native launch");auto effective=config;effective.global_bg_count=engines_.size();effective.channel_count=impl_->mem->channels.size();effective.ranks_per_channel=getConfigParam(UINT,"NUM_RANKS");effective.bank_groups_per_rank=getConfigParam(UINT,"NUM_BANK_GROUPS");effective.validate();partial_writeback_config_.reset(new CSCPartialResultPathConfig(effective));}
void CSCNativeExecution::tick(){if(!launched_||isTerminal())return;impl_->mem->update();cycle_++;stepPartialResultWriteback();if(bga_config_.enabled&&!execution_stats_.first_bga_output_cycle)for(uint32_t bg=0;bg<kCSCGlobalBGCount;++bg)if(bga_output_callbacks_.has_output(bg)){execution_stats_.first_bga_output_cycle=cycle_;break;}uint64_t barrier_epoch=std::numeric_limits<uint64_t>::max();if(scheduling_policy_==CSCSchedulingPolicy::BARRIER_LOCKSTEP_REFERENCE)for(auto&e:engines_)if(e->busy()&&!e->flushRequested()&&!e->hasFailed())barrier_epoch=std::min(barrier_epoch,e->progressEpoch());for(auto&e:engines_){if(failed_)break;const uint32_t bg=e->globalBG();if(e->hasFailed()){latchFailure(*e);break;}if(!e->busy()){execution_stats_.per_bg_idle_cycles[bg]++;continue;}if(scheduling_policy_==CSCSchedulingPolicy::BARRIER_LOCKSTEP_REFERENCE&&!e->flushRequested()&&!e->hasFailed()&&e->progressEpoch()>barrier_epoch){execution_stats_.per_bg_barrier_wait_cycles[bg]++;continue;}e->tick();if(e->hasFailed())latchFailure(*e);if(e->isTerminal()&&!execution_stats_.per_bg_completion_cycle[bg])execution_stats_.per_bg_completion_cycle[bg]=cycle_;}if(bga_config_.enabled&&!failed_){if(bgaComputeSubmitComplete()&&!execution_stats_.compute_submit_complete_cycle)execution_stats_.compute_submit_complete_cycle=cycle_;serviceValidationBGAOutputs();servicePartialWritebackBGAOutputs();if(bgaDrainComplete()&&!execution_stats_.bga_drain_complete_cycle)execution_stats_.bga_drain_complete_cycle=cycle_;if(bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::EXTERNAL&&bgaExecutionState()==CSCBGAExecutionState::WAITING_FOR_EXTERNAL_OUTPUT_CONSUMER)saturatingIncrement(execution_stats_.external_consumer_wait_cycles);if(bgaExecutionComplete()&&!execution_stats_.bga_execution_complete_cycle)execution_stats_.bga_execution_complete_cycle=cycle_;}updateMLP();finalizeEndToEnd();if(flush_requested_&&isDone())flush_completed_=true;}
bool CSCNativeExecution::busy()const{return launched_&&!isTerminal();}bool CSCNativeExecution::hasPendingTransactions()const{return impl_->mem->hasPendingTransactions();}bool CSCNativeExecution::hasUnconsumedCompletion()const{for(auto&e:engines_)if(e->tracker().pendingCount())return true;return false;}
bool CSCNativeExecution::isTerminal()const{if(!launched_||!outstanding_.empty())return false;if(failed_)return true;if(bga_config_.enabled){if(bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::PARTIAL_RESULT_WRITEBACK)return endToEndSpMVComplete();return bgaExecutionComplete();}for(auto&e:engines_)if(!e->isTerminal())return false;return true;}bool CSCNativeExecution::isDone()const{if(bga_config_.enabled){if(bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::PARTIAL_RESULT_WRITEBACK)return endToEndSpMVComplete();return bgaExecutionComplete();}if(!isTerminal()||failed_)return false;for(auto&e:engines_)if(!e->isDone())return false;return true;}
void CSCNativeExecution::flushBG(uint32_t bg){if(bg>=64)throw std::out_of_range("CSC BG");auto*channel=impl_->mem->channels.at(bg/4);channel->ranks->at(0)->pimRank->flushBG(bg%4);engines_[bg]->flushIncomplete();result_status_[bg]=CSCResultStatus::INCOMPLETE_FLUSHED;}
bool CSCNativeExecution::resetBG(uint32_t bg){if(bg>=64)throw std::out_of_range("CSC BG");auto*channel=impl_->mem->channels.at(bg/4);if(!channel->ranks->at(0)->pimRank->resetBG(bg%4))return false;engines_[bg]->reset();result_status_[bg]=CSCResultStatus::RUNNING;return true;}
void CSCNativeExecution::flush(){flush_requested_=true;bool idle=!launched_;if(idle)launched_=true;for(auto&e:engines_)e->flush();if(idle)for(auto&e:engines_)e->tick();if(isDone())flush_completed_=true;}
bool CSCNativeExecution::resultValid()const{if(bga_config_.enabled){if(bga_config_.output_consumer_mode==CSCBGAOutputConsumerMode::PARTIAL_RESULT_WRITEBACK)return endToEndSpMVComplete();return false;}for(auto status:result_status_)if(status==CSCResultStatus::INCOMPLETE_FLUSHED||status==CSCResultStatus::ERROR)return false;return isDone();}
void CSCNativeExecution::reset(){if(!outstanding_.empty())throw std::logic_error("M5 reset with pending request");for(auto&e:engines_)e->reset();partials_.clear();partial_result_path_.reset();launched_=failed_=flush_requested_=flush_completed_=false;rows_=0;nnz_=0;host_accumulations_=0;error_code_=CSCError::NONE;failed_engine_=-1;error_message_.clear();execution_stats_={};bga_validation_collector_={};validation_round_robin_cursor_=partial_writeback_round_robin_cursor_=0;}
std::vector<float>CSCNativeExecution::hostAccumulate(){if(bga_config_.enabled)throw std::logic_error("M7A validation output is not a native final result");if(!isDone())throw std::logic_error("M5 accumulation before successful DONE");std::vector<double>s(rows_);host_accumulations_=0;for(auto&p:partials_){if(p.row_idx>=rows_)throw std::logic_error("M5 partial row range");s[p.row_idx]+=p.value;host_accumulations_++;}std::vector<float>y(rows_);for(size_t i=0;i<y.size();i++)y[i]=float(s[i]);return y;}
CSCExecutionCounters CSCNativeExecution::counters()const{auto t=execution_stats_;for(auto&e:engines_){auto&c=e->counters();t.descriptor_fetches+=c.descriptor_fetches;t.x_scalar_loads+=c.x_scalar_loads;t.x_transactions+=c.x_transactions;t.value_transactions+=c.value_transactions;t.index_transactions+=c.index_transactions;t.logical_mul_events+=c.logical_mul_events;t.full_chunks+=c.full_chunks;t.tail_chunks+=c.tail_chunks;t.total_chunks+=c.total_chunks;t.active_lanes+=c.active_lanes;t.available_lanes+=c.available_lanes;t.invalid_lane_multiplies+=c.invalid_lane_multiplies;t.invalid_lane_writes+=c.invalid_lane_writes;t.generated_partials+=c.generated_partials;t.emitted_partials+=c.emitted_partials;t.generated_bga_batches+=c.generated_bga_batches;t.generated_bga_partials+=c.generated_bga_partials;t.accepted_bga_batches+=c.accepted_bga_batches;t.accepted_bga_partials+=c.accepted_bga_partials;t.bga_backpressure_cycles+=c.bga_backpressure_cycles;t.bga_duplicate_errors+=c.bga_duplicate_errors;t.bga_protocol_errors+=c.bga_protocol_errors;t.bga_producer_done_calls+=c.bga_producer_done_calls;t.bga_final_drain_requests+=c.bga_final_drain_requests;t.empty_bg_producer_completions+=c.empty_bg_producer_completions;t.stall_cycles_request+=c.stall_cycles_request;t.stall_cycles_backpressure+=c.stall_cycles_backpressure;t.busy_cycles+=c.busy_cycles;auto&s=e->tracker().stats();t.created_requests+=s.created_requests;t.submit_attempts+=s.submit_attempts;t.accepted_requests+=s.issued;t.abandoned_waiting_requests+=s.abandoned_waiting_requests;t.submit_rejections+=s.submit_rejected;t.retry_count+=s.retries;t.unknown_completions+=s.unknown_completions;t.duplicate_completions+=s.duplicate_completions;t.stale_generation_completions+=s.stale_generation_completions;t.request_kind_mismatches+=s.kind_mismatches;t.owner_mismatches+=s.owner_mismatches;t.completion_after_retirement+=s.completion_after_retirement;t.maximum_waiting_to_submit_depth=std::max(t.maximum_waiting_to_submit_depth,s.maximum_waiting_to_submit_depth);for(size_t k=0;k<kCSCRequestKindCount;k++){t.issued_by_kind[k]+=s.issued_by_kind[k];t.abandoned_by_kind[k]+=s.abandoned_by_kind[k];}for(size_t bg=0;bg<kCSCGlobalBGCount;bg++)t.abandoned_by_bg[bg]+=s.abandoned_by_bg[bg];t.issued_by_bg[e->globalBG()]+=s.issued;}for(uint32_t channel=0;channel<impl_->mem->channels.size();++channel){auto*rank=impl_->mem->channels[channel]->ranks->at(0);const auto&s=rank->pimRank->targetedStatistics();for(uint32_t bg=0;bg<4;++bg){uint32_t global=channel*4+bg;t.per_bg_ready_cycles[global]=s.per_bg_ready_cycles[bg];t.per_bg_executing_cycles[global]=s.per_bg_executing_cycles[bg];t.per_bg_grant_wait_cycles[global]=s.per_bg_grant_wait_cycles[bg];t.per_bg_flush_drain_cycles[global]=s.per_bg_flush_drain_cycles[bg];t.per_bg_memory_wait_cycles[global]=engines_[global]->counters().stall_cycles_request;}for(uint32_t block=0;block<8;++block){t.per_pimblock_active_cycles[channel*8+block]=s.per_pimblock_active_cycles[block];t.per_pimblock_targeted_ops[channel*8+block]=s.per_pimblock_targeted_ops[block];}t.rank_targeted_grants+=s.rank_targeted_grants;t.rank_command_bus_stall_cycles+=s.rank_command_bus_stall_cycles;t.rank_resource_conflict_stall_cycles+=s.rank_resource_conflict_stall_cycles;t.rank_mode_drain_cycles+=s.rank_mode_drain_cycles;t.round_robin_skip_count+=s.round_robin_skip_count;}t.host_accumulations=host_accumulations_;t.launch_to_done_cycles=cycle_;t.total_execution_cycles=t.launch_to_done_cycles;t.scheduling_policy=scheduling_policy_;t.total_cycles=cycle_;for(auto wait:t.per_bg_barrier_wait_cycles)t.total_barrier_wait_cycles+=wait;t.memory_requests_accepted=t.accepted_requests;t.memory_requests_completed=t.completion_count;t.targeted_ops_accepted=t.rank_targeted_grants;t.targeted_ops_completed=t.rank_targeted_grants;t.partial_results_emitted=t.emitted_partials;if(t.cycles_with_outstanding_ge_1)t.average_outstanding=double(t.outstanding_cycle_integral)/t.cycles_with_outstanding_ge_1;t.t_compute_submit=t.compute_submit_complete_cycle>=t.execution_start_cycle?t.compute_submit_complete_cycle-t.execution_start_cycle:0;t.t_bga_drain=t.bga_drain_complete_cycle>=t.execution_start_cycle?t.bga_drain_complete_cycle-t.execution_start_cycle:0;if(partial_result_path_){const auto&w=partial_result_path_->counters();const auto&r=partial_result_path_->readbackCounters();const auto&h=partial_result_path_->reductionCounters();t.t_writeback=w.partial_writeback_complete_cycle>=w.first_bga_output_accept_cycle?w.partial_writeback_complete_cycle-w.first_bga_output_accept_cycle:0;t.t_readback=h.host_readback_complete_cycle>=r.host_readback_start_cycle?h.host_readback_complete_cycle-r.host_readback_start_cycle:0;t.t_host_reduce=h.host_reduction_complete_cycle>=h.first_returned_burst_accept_cycle?h.host_reduction_complete_cycle-h.first_returned_burst_accept_cycle:0;}t.t_end_to_end=t.end_to_end_complete_cycle>=t.execution_start_cycle?t.end_to_end_complete_cycle-t.execution_start_cycle:0;return t;}
